			function onBtn1Click(e) {
			    var btn1 = e.control;
			    
			    var dsList = app.lookup("dsList");
			    var dsMentor = app.lookup("dsMentor");
			    var dsMentee = app.lookup("dsMentee");
			    var mentorSelIndex = app.lookup("grd1").getRadioSelection();
			    var menteeSelIndices = app.lookup("grd2").getCheckRowIndices();
			    var menteeList = dsList.getColumnData("MENTEE_NO");
			    
			    if (userInfo["REG_BUTTON_USE_YN"] != "Y") {
			        util.Msg.alert(app, "등록 권한이 없습니다.");
			        return;
			    }
			    
			    if (mentorSelIndex == -1) {
			        util.Msg.alert(app, "WRN-M001", "멘토 ");
			        return false;
			    }
			    if (menteeSelIndices.length == 0) {
			        util.Msg.alert(app, "WRN-M001", "멘티 ");
			        return false;
			    }
			    
			    menteeSelIndices.forEach(function(each) {
			        
			        var addMentee = dsMentee.getRowData(each);
			        var addMentor = dsMentor.getRowData(mentorSelIndex);
			        if (menteeList.includes(addMentee["MENTEE_NO"]))
			            return false;
			        dsList.insertRowData(0, false, addMentee);
			        dsList.updateRow(0, addMentor);
			    });
			    
			    app.lookup("grd1").removeRadioSelection();
			    app.lookup("grd2").clearAllCheck();
			}

